import Redis from "ioredis";

export interface Profile {
  id: string;
  [field: string]: unknown;
}

const TTL_SECONDS = 300;
const MISS_TTL_SECONDS = 30;
const MISS = "__miss__";

export class ProfileCache {
  private inflight = new Map<string, Promise<Profile | null>>();

  constructor(
    private redis: Redis,
    private load: (id: string) => Promise<Profile | null>,
  ) {}

  private key(id: string): string {
    return `profile:v1:${id}`;
  }

  async get(id: string): Promise<Profile | null> {
    const key = this.key(id);
    try {
      const hit = await this.redis.get(key);
      if (hit !== null) return hit === MISS ? null : JSON.parse(hit);
    } catch {
      // Redis down: fall through to the source
    }

    // Collapse concurrent misses for the same id into one load
    let pending = this.inflight.get(key);
    if (!pending) {
      pending = this.fill(id, key).finally(() => this.inflight.delete(key));
      this.inflight.set(key, pending);
    }
    return pending;
  }

  private async fill(id: string, key: string): Promise<Profile | null> {
    const profile = await this.load(id);
    try {
      await this.redis.set(
        key,
        profile ? JSON.stringify(profile) : MISS,
        "EX",
        profile ? TTL_SECONDS : MISS_TTL_SECONDS,
      );
    } catch {
      // Cache write failure must not fail the request
    }
    return profile;
  }

  async invalidate(id: string): Promise<void> {
    await this.redis.del(this.key(id));
  }
}
```

